public class Bits {
    public static void main(String[] args) {
        int a = 0b1100, b = 0b1010;
        System.out.println(Integer.toBinaryString(a & b) + " " + Integer.toBinaryString(a | b)
            + " " + Integer.toBinaryString(a ^ b) + " " + (~a));
        System.out.println((-16 >> 2) + " " + (-16 >>> 28) + " " + (-16 >>> 2) + " " + (1 << 33)
            + " " + (1L << 33));
        System.out.println(Integer.toBinaryString(-16));
        int flags = 0;
        final int READ = 1, WRITE = 2, EXEC = 4;
        flags |= READ | EXEC;
        System.out.println(flags + " " + ((flags & WRITE) != 0) + " " + ((flags & EXEC) != 0));
        flags &= ~EXEC;
        System.out.println(flags);
        System.out.println((5 & 1) == 1 ? "odd" : "even");
        System.out.println(Integer.bitCount(255) + " " + Integer.toHexString(255) + " "
            + Integer.highestOneBit(100));
    }
}

