public class Flow {
    enum Day { MON, TUE, SAT, SUN }

    static int oldSwitch(int n) {
        int r = 0;
        switch (n) {
            case 1:
                r += 1;
            case 2:
                r += 2;
                break;
            case 3:
                r += 3;
                break;
            default:
                r = -1;
        }
        return r;
    }

    static String kind(Day d) {
        return switch (d) {
            case SAT, SUN -> "weekend";
            case MON, TUE -> {
                String s = "week";
                yield s + "day";
            }
        };
    }

    static int oldYield(String s) {
        return switch (s) {
            case "a":
            case "b":
                yield 1;
            default:
                yield 0;
        };
    }

    static String describe(Object o) {
        return switch (o) {
            case null -> "null!";
            case Integer i when i > 100 -> "big int " + i;
            case Integer i -> "int " + i;
            case String s -> "string of length " + s.length();
            default -> "something else: " + o;
        };
    }

    public static void main(String[] args) {
        System.out.println(oldSwitch(1) + " " + oldSwitch(2) + " " + oldSwitch(3)
            + " " + oldSwitch(9));
        System.out.println(kind(Day.SUN) + " " + kind(Day.MON) + " " + oldYield("b"));
        System.out.println(describe(5) + "; " + describe(500) + "; " + describe("hey"));
        System.out.println(describe(2.5) + "; " + describe(null));
        int total = 0;
        for (int i = 1; i <= 10; i++) {
            if (i % 2 == 0) continue;
            if (i > 7) break;
            total += i;
        }
        System.out.println(total);
        outer:
        for (int r = 1; r <= 3; r++) {
            for (int c = 1; c <= 3; c++) {
                if (c == 2) continue outer;
                if (r == 3) break outer;
                System.out.print(r + "" + c + " ");
            }
        }
        System.out.println();
        int n = 0;
        do { n++; } while (n < 0);
        System.out.println(n);
        String[] names = {"Asha", "Ravi", "Meera"};
        for (String nm : names) System.out.print(nm.charAt(0));
        System.out.println();
        for (int i = 0, j = 10; i < j; i += 3, j -= 3) System.out.print(i + ":" + j + " ");
        System.out.println();

    }
}

import java.util.ArrayList;
import java.util.List;

public class Pitfalls {
    public static void main(String[] args) {
        int count = 0;
        for (double x = 0.0; x != 1.0; x += 0.1) {
            if (++count > 15) {
                System.out.println("0.1 steps never hit 1.0 exactly; stopped after " + count);
                break;
            }
        }
        int[] a = {1, 2, 3};
        try {
            for (int i = 0; i <= a.length; i++) System.out.print(a[i] + " ");
        } catch (ArrayIndexOutOfBoundsException e) {
            System.out.println("-> " + e.getMessage());
        }
        List<String> names = new ArrayList<>(List.of("a", "b", "c"));
        try {
            for (String s : names) if (s.equals("a")) names.remove(s);
        } catch (java.util.ConcurrentModificationException e) {
            System.out.println("CME");
        }
        names.removeIf(s -> s.equals("b"));
        System.out.println(names);
        int x = 5;
        if (x > 3)
            if (x > 10)
                System.out.println("big");
            else
                System.out.println("dangling else belongs to the inner if");
    }
}

