import java.util.Arrays;

public class Varargs {
    static int sum(int... nums) {
        int t = 0;
        for (int n : nums) t += n;
        return t;
    }
    static String show(String label, Object... items) {
        return label + ":" + (items == null ? "null array" : items.length);
    }
    public static void main(String[] args) {
        System.out.println(sum() + " " + sum(1) + " " + sum(1, 2, 3) + " " + sum(new int[]{4, 5}));
        System.out.println(show("a") + " " + show("b", 1, 2) + " " + show("c", (Object[]) null));
        String[] xs = {"x", "y", "z"};
        System.out.println(show("d", (Object[]) xs) + " " + show("e", (Object) xs));
        int[][] m = {{1, 2}, {3, 4}, {5, 6}};
        long total = 0;
        for (int[] row : m) for (int v : row) total += v;
        System.out.println(total + " " + m.length + " " + m[0].length + " "
            + Arrays.toString(m[2]));
    }
}

public class Anatomy {
    // modifiers  return type  name   parameters          throws
    public static int clamp(int value, int min, int max) {
        if (min > max) {
            throw new IllegalArgumentException("min > max");
        }
        return Math.max(min, Math.min(max, value));
    }

    public static void main(String[] args) {
        System.out.println(clamp(15, 0, 10));
    }
}

public class Overload {
