public class PassByValue {
    static void reassign(StringBuilder sb) { sb = new StringBuilder("new"); }
    static void mutate(StringBuilder sb)   { sb.append("!"); }
    static void bump(int n)                { n++; }
    static void swap(int[] a)              { int t = a[0]; a[0] = a[1]; a[1] = t; }

    public static void main(String[] args) {
        int n = 1;
        bump(n);
        System.out.println("n = " + n);

        StringBuilder sb = new StringBuilder("old");
        reassign(sb);
        System.out.println("after reassign: " + sb);
        mutate(sb);
        System.out.println("after mutate:   " + sb);

        int[] pair = {1, 2};
        swap(pair);
        System.out.println(java.util.Arrays.toString(pair));
    }
}

public class Recur {
    static int depth = 0;
    static void down() { depth++; down(); }
    static long fact(int n) { return n <= 1 ? 1 : n * fact(n - 1); }
    static long factLoop(int n) { long r = 1; for (int i = 2; i <= n; i++) r *= i; return r; }
    static long fib(int n) { return n < 2 ? n : fib(n - 1) + fib(n - 2); }

    public static void main(String[] args) {
        System.out.println(fact(5) + " " + factLoop(20) + " " + fib(20));
        try { down(); }
        catch (StackOverflowError e) {
            System.out.println("overflow after " + (depth > 1000 ? "thousands of" : "few")
                + " calls: " + e.getClass().getName());
        }
    }
}

